"""Finite-type verification of Lawvere/Cantor: no g : A -> (A -> Bool) is
point-surjective, exhibited by brute force plus the diagonal witness."""
from itertools import product
from typing import Callable, List, Tuple


def all_predicates(n: int) -> List[Tuple[bool, ...]]:
    return list(product([False, True], repeat=n))


def any_surjective(n: int) -> bool:
    preds = all_predicates(n)
    for assignment in product(preds, repeat=n):
        reached = {assignment[a] for a in range(n)}
        if reached == set(preds):
            return True
    return False


def diagonal_missing(g: Callable[[int], Tuple[bool, ...]], n: int) -> Tuple[bool, ...]:
    return tuple((not g(a)[a]) for a in range(n))


if __name__ == "__main__":
    for n in (1, 2, 3):
        print(f"|A|={n}: some g surjective onto (A->Bool)? {any_surjective(n)}")
    g = lambda a: {0: (True, False, True),
                   1: (False, False, True),
                   2: (True, True, True)}[a]
    print("diagonal predicate never in image:", diagonal_missing(g, 3))

"""Simulation Theorem demo: a genuinely self-modifying machine halts iff its
fixed-program ('code as data') simulation halts, checked over many starts."""
from typing import Callable, Optional, Tuple

Config = Tuple[object, object]


def selfmod_halts(step: Callable[[object, object], Optional[Config]],
                  cfg: Config, bound: int) -> bool:
    for n in range(bound + 1):
        cur: Optional[Config] = cfg
        halted = False
        for _ in range(n):
            assert cur is not None
            cur = step(cur[0], cur[1])
            if cur is None:
                halted = True
                break
        if halted:
            return True
    return False


def std_halts(step: Callable[[object, object], Optional[Config]],
              cfg: Config, bound: int) -> bool:
    # standard simulation: identical step, program absorbed into combined state
    for n in range(bound + 1):
        cur: Optional[Config] = cfg
        halted = False
        for _ in range(n):
            assert cur is not None
            cur = step(cur[0], cur[1])
            if cur is None:
                halted = True
                break
        if halted:
            return True
    return False


def step(prog: object, state: object) -> Optional[Config]:
    s = int(state)  # type: ignore[arg-type]
    if s == 0:
        return None
    return ("dec", s + 1) if prog == "inc" else ("inc", s - 1)


if __name__ == "__main__":
    for start in [("inc", 0), ("inc", 1), ("dec", 1), ("dec", 5)]:
        a = selfmod_halts(step, start, 50)
        b = std_halts(step, start, 50)
        print(f"{str(start):>14}: self-mod={a}, std-sim={b}, agree={a==b}")

"""Bridge Lemma demo: the diagonal self-modifying machine halts on program c
(input n) iff c classically halts on n, via a bounded universal evaluator."""
from typing import Callable, Optional

Program = Callable[[int, int], Optional[int]]


def evaln(budget: int, prog: Program, n: int) -> Optional[int]:
    return prog(n, budget)


def diag_halts(prog: Program, n: int, bound: int) -> bool:
    s = 0
    for _ in range(bound + 1):
        if evaln(s, prog, n) is not None:
            return True
        s += 1
    return False


def classical_halts(prog: Program, n: int, bound: int) -> bool:
    return any(evaln(b, prog, n) is not None for b in range(bound + 1))


if __name__ == "__main__":
    conv_at_n: Program = lambda n, b: (42 if b >= n else None)
    even_only: Program = lambda n, b: (7 if (n % 2 == 0 and b >= 2) else None)
    for name, prog, n in [("conv_at_n", conv_at_n, 5),
                          ("conv_at_n", conv_at_n, 20),
                          ("even_only", even_only, 4),
                          ("even_only", even_only, 7)]:
        d = diag_halts(prog, n, 30)
        c = classical_halts(prog, n, 30)
        print(f"{name}(n={n}): diag={d}, classical={c}, agree={d==c}")

