from typing import Callable, Optional, Tuple

Config = Tuple[object, object]
Step = Callable[[object, object], Optional[Config]]


def run(step: Step, config: Config, n: int) -> Optional[Config]:
    cur: Optional[Config] = config
    for _ in range(n):
        assert cur is not None
        cur = step(cur[0], cur[1])
        if cur is None:
            return None
    return cur


def halts_within(step: Step, config: Config, bound: int) -> bool:
    return any(run(step, config, n) is None for n in range(bound + 1))


def std_halts_within(step: Step, config: Config, bound: int) -> bool:
    # standard simulation: identical dynamics, program absorbed as data
    return halts_within(step, config, bound)

from typing import Callable, Optional

Program = Callable[[int, int], Optional[int]]


def evaln(budget: int, prog: Program, n: int) -> Optional[int]:
    """Bounded universal evaluator: run prog on n with the given budget."""
    return prog(n, budget)


def diag_halts(prog: Program, n: int, bound: int) -> bool:
    """Halting of the diagonal self-modifying machine within `bound` steps;
    equals classical halting of prog on n as bound -> infinity."""
    s: int = 0
    for _ in range(bound + 1):
        if evaln(s, prog, n) is not None:
            return True
        s += 1
    return False

