from typing import Dict, List, Tuple


def behavioral_fixed_points(
    behavior: Dict[str, Tuple[int, ...]],
    modify: Dict[str, str],
) -> List[str]:
    """Return codes whose behaviour the rewrite `modify` leaves unchanged."""
    fixed: List[str] = []
    for code, beh in behavior.items():
        if behavior[modify[code]] == beh:
            fixed.append(code)
    return fixed
